class Solution {
    public int[] smallestSufficientTeam(String[] reqSkills,List<List<String>> people){
        Map<String,Integer> skill=new HashMap<>();
        for(int i=0;i<reqSkills.length;i++)skill.put(reqSkills[i],i);
        Map<Integer,List<Integer>> dp=new HashMap<>();
        dp.put(0,new ArrayList<>());
        for(int person=0;person<people.size();person++){
            int personMask=0;
            for(String name:people.get(person))personMask|=1<<skill.get(name);
            List<Map.Entry<Integer,List<Integer>>> snapshot=new ArrayList<>(dp.entrySet());
            for(Map.Entry<Integer,List<Integer>> entry:snapshot){
                int next=entry.getKey()|personMask;
                List<Integer> current=dp.get(next);
                if(current==null||current.size()>entry.getValue().size()+1){
                    List<Integer> team=new ArrayList<>(entry.getValue());
                    team.add(person);
                    dp.put(next,team);
                }
            }
        }
        return dp.get((1<<reqSkills.length)-1).stream().mapToInt(Integer::intValue).toArray();
    }
}

code.kotlin:
class Solution {
    fun smallestSufficientTeam(reqSkills:Array<String>,people:List<List<String>>):IntArray{
        val skill=reqSkills.withIndex().associate{
            it.value to it.index
        };
        val dp=mutableMapOf<Int,List<Int>>(0 to emptyList());
        for(person in people.indices){
            var personMask=0;
            for(name in people[person])personMask=personMask or (1 shl skill[name]!!);
            for((mask,team) in dp.toList()){
                val next=mask or personMask;
                if(next !in dp||dp[next]!!.size>team.size+1)dp[next]=team+person
            }
        };
        return dp[(1 shl reqSkills.size)-1]!!.toIntArray()
    }
}

